def mark_updated_terms(body, updates):
    """Keep current-name highlights in translated prose without editing tags."""
    names = {}
    for update in updates:
        name = update['new']
        if name.endswith(' page'):
            name = name[:-5]
        names[html.escape(name)] = update['old']
    if not names:
        return body
    pattern = re.compile('|'.join(re.escape(n) for n in sorted(names, key=len, reverse=True)))
    parts = re.split(r'(<[^>]*>)', body)
    for i in range(0, len(parts), 2):
        parts[i] = pattern.sub(lambda m: '<span class="rn-new" title="আগের নাম: ' + html.escape(names[m.group()], quote=True) + '">' + m.group() + '</span>', parts[i])
    return ''.join(parts)


def original_bangla(question):
    explanation = question['explain']
    pattern = r'<p><strong>Source correction:</strong>.*?</p>'
    if re.search(pattern, explanation, re.S):
        assert question['uid'] in ORIGINAL_CORRECTIONS, question['uid']
        correction = ORIGINAL_CORRECTIONS[question['uid']]
        explanation = re.sub(pattern, lambda _: '<p><strong>মূল প্রশ্নের সংশোধন:</strong> ' + html.escape(correction) + '</p>', explanation, flags=re.S)
        question['correction'] = correction
    explanation = explanation.replace('Databricks documentation', 'Databricks-এর ডকুমেন্টেশন').replace('Downloaded source', 'ডাউনলোড করা মূল উৎস').replace('Previously:', 'আগের নাম:')
    question['explain'] = explanation
    return question


def downloaded_bangla(source, answer, collection_link):
    uid = source['id']
    assert uid in DOWNLOAD_BODIES, uid
    explanation = '<p class="ans">✅ সঠিক উত্তর: ' + ', '.join(answer) + '</p>'
    if source['corrections']:
        assert uid in DOWNLOAD_CORRECTIONS, uid
        assert len(source['corrections']) == len(DOWNLOAD_CORRECTIONS[uid]), uid
        explanation += '<h3>মূল প্রশ্নের সংশোধন</h3><ul>' + ''.join('<li>' + html.escape(note) + '</li>' for note in DOWNLOAD_CORRECTIONS[uid]) + '</ul>'
    explanation += '<h3>ব্যাখ্যা</h3>' + mark_updated_terms(DOWNLOAD_BODIES[uid], source['updates'])
    if source['sourceAnswerVaries']:
        explanation += '<p class="syllabus-note">ডাউনলোড করা উৎসের বিভিন্ন সংস্করণে চিহ্নিত উত্তরের wording আলাদা। মূল সংস্করণগুলো উৎসসংগ্রহে রাখা আছে; উপরে কোনো সংশোধন থাকলে সেটিই এই প্রশ্নে অনুসরণ করতে হবে।</p>'
    explanation += '<h3>সিলেবাসের সঙ্গে সম্পর্ক</h3><p>মে ২০২৬ পরীক্ষার নির্দেশিকা — ' + html.escape(OBJECTIVES_BN[source['sec']]) + '</p><h3>তথ্যসূত্র</h3>'
    for url in source['documentation']:
        explanation += '<p><a href="' + html.escape(url, quote=True) + '" target="_blank" rel="noopener noreferrer">Databricks-এর ডকুমেন্টেশন</a></p>'
    explanation += '<p><a href="' + html.escape(source['url'], quote=True) + '" target="_blank" rel="noopener noreferrer">মূল উৎসের প্রশ্ন</a> · <a href="' + collection_link + '" target="_blank" rel="noopener noreferrer">উৎসের সব সংস্করণ</a></p>'
    return explanation
